selector_to_html = {"a[href=\"run-on-hardware.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Run on Hardware<a class=\"headerlink\" href=\"#run-on-hardware\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum keeps one execution contract across local, remote compute, and quantum-hardware targets. The circuit and the requested observable stay explicit; the target changes where the program runs, not what the result means.</p>", "a[href=\"#a-hybrid-classical-quantum-model\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">A hybrid classical-quantum model<a class=\"headerlink\" href=\"#a-hybrid-classical-quantum-model\" title=\"Link to this heading\">#</a></h2><p>Quantum layers compose with ordinary PyTorch layers. For a complete workflow, run the repository example:</p>", "a[href=\"training-with-pytorch.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Training with PyTorch<a class=\"headerlink\" href=\"#training-with-pytorch\" title=\"Link to this heading\">#</a></h1><p>Execution and training are intentionally separate. A trainable program is an\n<code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Module</span></code> inside an ordinary PyTorch training loop.</p>", "a[href=\"#next-steps\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Next steps<a class=\"headerlink\" href=\"#next-steps\" title=\"Link to this heading\">#</a></h2>", "a[href=\"build-and-run.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Build and Run<a class=\"headerlink\" href=\"#build-and-run\" title=\"Link to this heading\">#</a></h1><h2>Build a circuit<a class=\"headerlink\" href=\"#build-a-circuit\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">n_qubits</span></code> is the preferred public spelling for circuit size. Positional construction, <code class=\"docutils literal notranslate\"><span class=\"pre\">n_wires=</span></code>, and Qiskit-compatible <code class=\"docutils literal notranslate\"><span class=\"pre\">num_qubits</span></code> remain available, and conflicting aliases fail during construction instead of being resolved silently.</p><p>Generated gate methods keep their concise positional form and also accept semantic qubit keywords: <code class=\"docutils literal notranslate\"><span class=\"pre\">h(0)</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">h(qubit=0)</span></code> are equivalent, <code class=\"docutils literal notranslate\"><span class=\"pre\">cx(0,</span> <span class=\"pre\">1)</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">cx(control=0,</span> <span class=\"pre\">target=1)</span></code> are equivalent, and symmetric two-qubit gates take <code class=\"docutils literal notranslate\"><span class=\"pre\">qubit1=</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">qubit2=</span></code>.</p>", "a[href=\"#build-train-and-measure\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Build, train, and measure<a class=\"headerlink\" href=\"#build-train-and-measure\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Module</span></code> exposes the quantum model to PyTorch, <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.train</span></code> owns the optimizer loop, and <code class=\"docutils literal notranslate\"><span class=\"pre\">outputs</span></code> selects what to measure after training.</p>", "a[href=\"#first-quantum-model\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">First Quantum Model<a class=\"headerlink\" href=\"#first-quantum-model\" title=\"Link to this heading\">#</a></h1><p>This page trains a small quantum model end to end. It needs only the base installation.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
